/**
 * schema.org vocabulary check for JSON-LD.
 *
 * Flags `@type` values that are not schema.org types, properties that do not
 * exist in schema.org, properties used on a type outside their domain, and an
 * `@context` that does not point at schema.org. Search engines silently ignore
 * such markup, so typos ("Prodcut", "autor") quietly cost rich results.
 *
 * Vocabulary: lib/data/schema-org-vocab.json, generated by
 * scripts/build-schema-vocab.ts from the official schema.org JSON-LD release.
 */

import vocab from '../../data/schema-org-vocab.json';

export type VocabFindingKind = 'unknown-type' | 'unknown-property' | 'property-not-for-type' | 'bad-context';

export interface VocabFinding {
  kind: VocabFindingKind;
  /** Dotted path to the node, e.g. "Product.offers" */
  path: string;
  type?: string;
  property?: string;
  /** Closest known name for typos, when one is near enough */
  suggestion?: string;
}

const TYPES = vocab.types as Record<string, string[]>;
const PROPERTIES = vocab.properties as Record<string, string[]>;

/** Max findings per top-level schema, to keep a broken template from flooding the report. */
const MAX_FINDINGS = 20;
const MAX_DEPTH = 12;

const ancestorCache = new Map<string, Set<string>>();

/** The type plus all its schema.org superclasses. */
export function typeAncestors(type: string): Set<string> {
  const cached = ancestorCache.get(type);
  if (cached) return cached;
  const out = new Set<string>();
  const stack = [type];
  while (stack.length > 0) {
    const t = stack.pop()!;
    if (out.has(t)) continue;
    out.add(t);
    for (const parent of TYPES[t] ?? []) stack.push(parent);
  }
  ancestorCache.set(type, out);
  return out;
}

const SCHEMA_IRI = /^https?:\/\/(www\.)?schema\.org\/?/i;

/**
 * Normalise a type or property name to a bare schema.org term.
 * Returns null for terms from another vocabulary (prefixed or absolute IRIs),
 * which this check leaves alone.
 */
function toSchemaTerm(raw: string): string | null {
  const s = raw.trim();
  if (SCHEMA_IRI.test(s)) return s.replace(SCHEMA_IRI, '');
  if (s.startsWith('schema:')) return s.slice('schema:'.length);
  if (s.includes(':') || s.includes('/')) return null;
  return s;
}

/** True when an @context value declares schema.org as the vocabulary. */
export function isSchemaOrgContext(context: unknown): boolean {
  if (typeof context === 'string') return SCHEMA_IRI.test(context.trim());
  if (Array.isArray(context)) return context.some(isSchemaOrgContext);
  if (context && typeof context === 'object') {
    const vocabIri = (context as Record<string, unknown>)['@vocab'];
    return typeof vocabIri === 'string' && SCHEMA_IRI.test(vocabIri.trim());
  }
  return false;
}

function levenshtein(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 2) return 3;
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let diag = prev[0];
    prev[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = prev[j];
      prev[j] = Math.min(prev[j] + 1, prev[j - 1] + 1, diag + (a[i - 1] === b[j - 1] ? 0 : 1));
      diag = tmp;
    }
  }
  return prev[b.length];
}

/** Closest known term within edit distance 2 (case-insensitive match wins outright). */
function suggest(term: string, known: Iterable<string>): string | undefined {
  const lower = term.toLowerCase();
  let best: string | undefined;
  let bestDist = 3;
  for (const k of known) {
    if (k.toLowerCase() === lower) return k;
    const d = levenshtein(lower, k.toLowerCase());
    if (d < bestDist) {
      bestDist = d;
      best = k;
    }
  }
  return term.length >= 4 ? best : undefined;
}

/** Suggest a property, preferring ones valid for the node's type ("autor" → author, not actor). */
function suggestProperty(prop: string, ancestors: Set<string>): string | undefined {
  const fitting = Object.keys(PROPERTIES).filter((p) => {
    const d = PROPERTIES[p];
    return d.length === 0 || d.some((t) => ancestors.has(t));
  });
  return suggest(prop, fitting) ?? suggest(prop, Object.keys(PROPERTIES));
}

/**
 * Validate one JSON-LD node (a top-level schema or an @graph item) against the
 * schema.org vocabulary. `context` is the effective @context for the node.
 */
export function validateSchemaVocabulary(node: unknown, context: unknown): VocabFinding[] {
  const findings: VocabFinding[] = [];
  if (!node || typeof node !== 'object' || Array.isArray(node)) return findings;

  if (!isSchemaOrgContext(context)) {
    // Absent or non-schema.org context: properties cannot be interpreted as
    // schema.org terms, so report once and skip the rest.
    findings.push({ kind: 'bad-context', path: '@context' });
    return findings;
  }

  const visit = (value: unknown, path: string, depth: number) => {
    if (findings.length >= MAX_FINDINGS || depth > MAX_DEPTH) return;
    if (Array.isArray(value)) {
      for (const item of value) visit(item, path, depth);
      return;
    }
    if (!value || typeof value !== 'object') return;
    const obj = value as Record<string, unknown>;

    // Resolve the node's types. Unknown or foreign types disable property checks
    // for this node (we cannot know its domain) but children are still visited.
    const rawTypes = obj['@type'] == null ? [] : Array.isArray(obj['@type']) ? obj['@type'] : [obj['@type']];
    const types: string[] = [];
    let checkProps = rawTypes.length > 0;
    for (const raw of rawTypes) {
      if (typeof raw !== 'string') continue;
      const term = toSchemaTerm(raw);
      if (term == null) {
        checkProps = false;
        continue;
      }
      if (TYPES[term]) {
        types.push(term);
      } else {
        checkProps = false;
        findings.push({ kind: 'unknown-type', path, type: raw, suggestion: suggest(term, Object.keys(TYPES)) });
      }
    }
    const label = types[0] ?? path;
    const ancestors = new Set<string>();
    for (const t of types) for (const a of typeAncestors(t)) ancestors.add(a);

    for (const [key, child] of Object.entries(obj)) {
      if (findings.length >= MAX_FINDINGS) return;
      if (key.startsWith('@')) continue;
      // Action annotations ("query-input", "target-output") constrain the base property.
      const term = toSchemaTerm(key);
      const prop = term?.replace(/-(input|output)$/, '') ?? null;
      const childPath = `${label}.${key}`;
      if (prop != null && checkProps) {
        const domains = PROPERTIES[prop];
        if (!domains) {
          findings.push({
            kind: 'unknown-property',
            path: childPath,
            type: label,
            property: key,
            suggestion: suggestProperty(prop, ancestors),
          });
        } else if (domains.length > 0 && !domains.some((d) => ancestors.has(d))) {
          findings.push({ kind: 'property-not-for-type', path: childPath, type: label, property: key });
        }
      }
      visit(child, childPath, depth + 1);
    }
  };

  visit(node, '', 0);
  return findings;
}
